@Test
public void testJsonFormatThread() throws Exception {
    String jsonOld = "hql|show tables\n" + "hql|show tables\n" + "hql|show tables\n" + "hql|show tables\n" + "hql|show tables\n" + "scala|val s=sqlContext.sql(\\\"show tables\\\")\\nshow(s)\\n\n" + "shell|sleep 100\\nfunction example {\\n echo $[$(date +%s%N)/1000000]\\n}\n" + "shell|ifconfig\n" + "shell|echo ${f}|\"variable\":{\"f\":\"linkis\"}\n" + "python|print(\\\"：hello world\\\") \\ndef world(id):\\n     print(id); \\n     world(${f})|\"variable\":{\"f\":\"36\"}\n" + "python|#!/usr/bin/python\\n# -*- coding:utf-8 -*-\\nimport time\\nimport sys,os\\nimport json\\n\\nargs='{\\\"user_name\\\": \\\"zychen\\\"}'\\nprint(args)\\ndict = json.loads(args)\\nusername = dict.get(\\\"user_name\\\")\\nprint(username)\n" + "python|import sys\\nprint (\\\"Python Version {}\\\".format(str(sys.version).replace('\\\\n', '')))";
    ExecutorService threadPool = Executors.newFixedThreadPool(10);
    for (int i = 0; i < 10; i++) {
        threadPool.execute(() -> {
            try {
                String jsonNew = VariableOperationUtils.replaces(zonedDateTime, jsonOld);
                assertEquals(jsonNew, jsonOld);
            } catch (VariableOperationFailedException e) {
                e.printStackTrace();
                throw new RuntimeException(e);
            }
        });
    }
    threadPool.shutdown();
    while (!threadPool.isTerminated()) {
        Thread.sleep(1000);
    }
}

